-- Every database function the browser calls must exist and be executable by the role that calls it.
-- Generated by scripts/generate-rpc-grant-test.mjs from the supabase.rpc() calls in src/ (do not edit by hand;
-- run `node scripts/generate-rpc-grant-test.mjs` after adding an RPC call). verify:sql-runtime-safety fails if
-- this list drifts from the source.
--
-- Why it matters: a migration that REVOKEs EXECUTE (hardening) while the app still calls the function makes
-- the feature fail in production with "permission denied for function", which static checks cannot see.
BEGIN;

SELECT '1..1';

CREATE TEMP TABLE browser_rpc_names (name text PRIMARY KEY) ON COMMIT DROP;

SELECT CASE
  WHEN count(*) = 0 THEN 'ok 1 - every browser RPC exists and is executable by anon or authenticated'
  ELSE 'not ok 1 - browser RPCs missing or not executable by anon/authenticated'
END
FROM (
  SELECT b.name FROM browser_rpc_names b
  WHERE NOT EXISTS (
    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = b.name
      AND (has_function_privilege('anon', p.oid, 'execute') OR has_function_privilege('authenticated', p.oid, 'execute'))
  )
) missing;

SELECT '# ' || b.name || ': no overload is executable by anon or authenticated (or the function does not exist)'
FROM browser_rpc_names b
WHERE NOT EXISTS (
  SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = b.name
    AND (has_function_privilege('anon', p.oid, 'execute') OR has_function_privilege('authenticated', p.oid, 'execute'))
)
ORDER BY b.name;

ROLLBACK;
